capture.recv_reset:
# [security] Drop a client-supplied Fastly-Client-IP at the true edge so a
# spoofed value cannot poison the captured client IP. Operator VCL running
# after this (priority above -100, before the priority-1 capture) may set
# the real source IP; the ip capture falls back to client.ip otherwise.
if (req.restarts == 0 && fastly.ff.visits_this_service == 0) {
  unset req.http.Fastly-Client-IP;
}

capture.fetch:
# [group-L] Record TTFB and capture origin metadata
if (req.http.X-Edge-Scoring-Pass != "1" && req.http.x-of-start != "") {
  declare local var.fetch_ttfb INTEGER;
  set var.fetch_ttfb = std.atoi(time.elapsed.usec);
  set var.fetch_ttfb -= std.atoi(req.http.x-of-start);
  set req.http.x-of-ttfb = var.fetch_ttfb;
  set req.http.x-of-connect  = beresp.handshake_time_to_origin_ms;
  set req.http.x-of-status   = beresp.status;
  set req.http.x-of-oip      = beresp.backend.ip;
  set req.http.x-of-oretries = req.restarts;
}

capture.error:
# [group-L] Capture timing for failed origin fetches
if (req.http.X-Edge-Scoring-Pass != "1" && req.http.x-of-start != "") {
  declare local var.error_ttfb INTEGER;
  set var.error_ttfb = std.atoi(time.elapsed.usec);
  set var.error_ttfb -= std.atoi(req.http.x-of-start);
  set req.http.x-of-ttfb = var.error_ttfb;
  set req.http.x-of-status   = obj.status;
  set req.http.x-of-oip      = req.backend.ip;
  set req.http.x-of-oretries = req.restarts;
}

capture.deliver:
# [group-L] Record TTLB, capture bytes, strip all internal headers
if (req.http.X-Edge-Scoring-Pass != "1" && req.http.x-of-start != "") {
  declare local var.ttlb INTEGER;
  set var.ttlb = std.atoi(time.elapsed.usec);
  set var.ttlb -= std.atoi(req.http.x-of-start);
  set req.http.x-of-ttlb = var.ttlb;
}
unset resp.http.x-of-start;

# Promote upstream metrics to req so this node can log them if it didn't generate its own
if (req.http.x-of-ttfb == "" && resp.http.x-of-ttfb != "") { set req.http.x-of-ttfb = resp.http.x-of-ttfb; }
if (req.http.x-of-ttlb == "" && resp.http.x-of-ttlb != "") { set req.http.x-of-ttlb = resp.http.x-of-ttlb; }
if (req.http.x-of-connect == "" && resp.http.x-of-connect != "") { set req.http.x-of-connect = resp.http.x-of-connect; }
if (req.http.x-of-status == "" && resp.http.x-of-status != "") { set req.http.x-of-status = resp.http.x-of-status; }
if (req.http.x-of-oip == "" && resp.http.x-of-oip != "") { set req.http.x-of-oip = resp.http.x-of-oip; }
