  if (resp.http.Fastly-Io-Transform-Stats ~ "ifsz=") {
    set req.http.x-fos-io-ifsz = regsub(resp.http.Fastly-Io-Transform-Stats, ".*ifsz=([0-9]+).*", "\1");
  }
  if (resp.http.Fastly-Io-Transform-Stats ~ "ofsz=") {
    set req.http.x-fos-io-ofsz = regsub(resp.http.Fastly-Io-Transform-Stats, ".*ofsz=([0-9]+).*", "\1");
  }
  if (resp.http.Fastly-Io-Transform-Stats ~ "ifmt=") {
    set req.http.x-fos-io-ifmt = regsub(resp.http.Fastly-Io-Transform-Stats, ".*ifmt=([a-zA-Z0-9]+).*", "\1");
  }
  if (resp.http.Fastly-Io-Transform-Stats ~ "ofmt=") {
    set req.http.x-fos-io-ofmt = regsub(resp.http.Fastly-Io-Transform-Stats, ".*ofmt=([a-zA-Z0-9]+).*", "\1");
  }
  if ((!req.http.x-fos-io-ifmt || req.http.x-fos-io-ifmt == "") && resp.http.Fastly-Io-Transform-Stats ~ "dc_fmt=") {
    set req.http.x-fos-io-ifmt = regsub(resp.http.Fastly-Io-Transform-Stats, ".*dc_fmt=([a-z0-9]+).*", "\1");
  }
}
