  set req.http.x-fos-edge-data:ua = substr(req.http.User-Agent, 0, 1000);
  set req.http.x-fos-edge-data:cmcd_bl = req.http.x-cmcd:bl;
  set req.http.x-fos-edge-data:cmcd_br = req.http.x-cmcd:br;
  set req.http.x-fos-edge-data:cmcd_bs = req.http.x-cmcd:bs;
  set req.http.x-fos-edge-data:cmcd_cid = req.http.x-cmcd:cid;
  set req.http.x-fos-edge-data:cmcd_d = req.http.x-cmcd:d;
  set req.http.x-fos-edge-data:cmcd_dl = req.http.x-cmcd:dl;
  set req.http.x-fos-edge-data:cmcd_mtp = req.http.x-cmcd:mtp;
  set req.http.x-fos-edge-data:cmcd_ot = req.http.x-cmcd:ot;
